#include <cstddef>
#include <iostream>

class GrowthModel {
    static constexpr std::size_t limit = 24;
    std::size_t size_ = 0;
    std::size_t capacity_ = 3;
    std::size_t relocations_ = 0;
    std::size_t writes_ = 0;

public:
    bool append() {
        if (size_ == limit) return false;
        if (size_ == capacity_) {
            if (capacity_ > limit / 2) return false;
            relocations_ += size_;
            writes_ += size_;
            capacity_ *= 2;
        }
        ++size_;
        ++writes_;
        return true;
    }

    void print() const {
        std::cout << "size=" << size_ << " capacity=" << capacity_
                  << " relocations=" << relocations_
                  << " writes=" << writes_ << '\n';
    }
};

int main() {
    GrowthModel model;
    model.print();
    for (int request = 1; request <= 25; ++request) {
        if (!model.append()) {
            std::cout << "request " << request << " rejected\n";
            model.print();
            break;
        }
        if (request == 3 || request == 4 || request == 7 ||
            request == 13 || request == 14 || request == 24)
            model.print();
    }
}
